/**
 * Synchronous stdout/stderr helpers.
 *
 * The reference program interleaves buffered `print()` output with a fatal
 * traceback on stderr and then exits with a non-zero status.  Node's async
 * stream writes can be lost when `process.exit()` runs, so every write here
 * goes through `writeSync` on the raw file descriptors: ordering and flushing
 * are then guaranteed even on the failure paths.
 */
import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

function writeAll(fd, text) {
  if (text === '') return;
  const buf = Buffer.from(text, 'utf8');
  let written = 0;
  while (written < buf.length) {
    try {
      written += writeSync(fd, buf, written, buf.length - written);
    } catch (err) {
      // A non-blocking pipe can refuse the write; retry instead of dying.
      if (err.code === 'EAGAIN') continue;
      if (err.code === 'EPIPE') return;
      throw err;
    }
  }
}

export function writeStdout(text) {
  writeAll(STDOUT_FD, text);
}

export function writeStderr(text) {
  writeAll(STDERR_FD, text);
}

/** Equivalent of Python's `print(value)` with the default end='\n'. */
export function print(text = '') {
  writeStdout(`${text}\n`);
}

