/**
 * Python-compatible `repr()` / `str()` formatting.
 *
 * Python values are modelled as: str -> JS string, int -> JS BigInt,
 * tuple -> JS array, None -> null, bool -> JS boolean.
 */

// Python's str.isprintable() is false for these general categories.  ASCII
// space is the one Zs code point that Python still considers printable.
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

function isPrintableChar(ch) {
  return ch === ' ' || !NON_PRINTABLE.test(ch);
}

function hexEscape(ch) {
  const cp = ch.codePointAt(0);
  if (cp < 0x100) return `\\x${cp.toString(16).padStart(2, '0')}`;
  if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/**
 * repr() of a str: single quotes by default, double quotes when the text
 * contains a single quote but no double quote.  Backslash, the active quote,
 * \t, \n, \r and every non-printable code point are escaped.
 */
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += `\\${ch}`;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (isPrintableChar(ch)) out += ch;
    else out += hexEscape(ch);
  }
  return out + quote;
}

/** repr() of an int (arbitrary precision, so BigInt). */
export function reprInt(value) {
  return value.toString();
}

/** repr() of a tuple, including the trailing comma of 1-tuples. */
export function reprTuple(items) {
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

/** repr() of a dict, given its items in insertion order. */
export function reprDict(items) {
  if (items.length === 0) return '{}';
  const body = items.map(([k, v]) => `${pyRepr(k)}: ${pyRepr(v)}`).join(', ');
  return `{${body}}`;
}

export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (value === null || value === undefined) return 'None';
  if (Array.isArray(value)) return reprTuple(value);
  if (typeof value === 'object' && typeof value.repr === 'function') return value.repr();
  return String(value);
}

/** str(): plain text for strings, repr() for everything else. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

