/**
 * Python's `int(str)` conversion, used as argparse's `type=int`.
 *
 * Accepted: surrounding Python whitespace, an optional sign, decimal digits of
 * any Unicode decimal-digit script, and single underscores *between* digits.
 * Rejected: empty text, floats, 0x/0o literals, leading/trailing/doubled
 * underscores.  Results are BigInt so precision is unbounded like Python's int.
 */

// Exactly the code points for which Python's str.isspace() is true.
const PY_WHITESPACE =
  '\t\n\v\f\r \x1c\x1d\x1e\x1f\x85\xa0 ' +
  '           ' +
  '    　';

const DECIMAL_DIGIT = /\p{Nd}/u;
const DIGIT_BODY = /^\p{Nd}(?:_?\p{Nd})*$/u;

export class IntConversionError extends Error {}

function stripPyWhitespace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && PY_WHITESPACE.includes(text[start])) start += 1;
  while (end > start && PY_WHITESPACE.includes(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

/**
 * Numeric value of a Unicode decimal digit.  Each decimal-digit block is a
 * contiguous run of ten code points starting at its zero, so walking down to
 * the first non-digit yields the value.  The mathematical alphanumeric digits
 * are the one place where such blocks sit back to back, so they are indexed
 * directly.
 */
function digitValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x1d7ce && cp <= 0x1d7ff) return (cp - 0x1d7ce) % 10;
  let value = 0;
  while (value < 9 && DECIMAL_DIGIT.test(String.fromCodePoint(cp - value - 1))) value += 1;
  return value;
}

export function pyInt(text) {
  const stripped = stripPyWhitespace(text);
  let sign = 1n;
  let body = stripped;
  if (body.startsWith('+')) body = body.slice(1);
  else if (body.startsWith('-')) {
    sign = -1n;
    body = body.slice(1);
  }
  if (!DIGIT_BODY.test(body)) {
    throw new IntConversionError(`invalid literal for int() with base 10: ${text}`);
  }
  let digits = '';
  for (const ch of body) {
    if (ch !== '_') digits += String(digitValue(ch));
  }
  return sign * BigInt(digits);
}

