/**
 * Hash-key encoding for the Python-like values stored in a bidict.
 *
 * Each hashable value is projected onto a unique string so that plain
 * null-prototype objects can serve as O(1) lookup indexes.  Values that Python
 * considers equal (True == 1, 5.0 == 5) encode identically.
 */

export class UnhashableTypeError extends Error {}

export function encodePyKey(value) {
  switch (typeof value) {
    case 'string':
      return `s:${value}`;
    case 'bigint':
      return `i:${value.toString()}`;
    case 'boolean':
      return `i:${value ? 1 : 0}`;
    case 'number':
      return Number.isInteger(value) ? `i:${value}` : `f:${value}`;
    case 'undefined':
      return 'n:';
    case 'object':
      if (value === null) return 'n:';
      if (Array.isArray(value)) return `t:${value.map(encodePyKey).join('�,')}`;
      break;
    default:
      break;
  }
  throw new UnhashableTypeError(`unhashable type: ${typeof value}`);
}

