 * two directions.
 *
 * Order is held in an explicit array of slots because JS objects reorder
 * integer-like property names ('7' would sort before 'a'), which would corrupt
 * dict ordering for numeric keys.  A null-prototype object indexes encoded keys
 * to slot positions so lookups stay O(1) and names such as '__proto__' or
 * 'toString' behave like any other key.
 */
import { encodePyKey } from './pykey.mjs';

export const MISSING = Symbol('MISSING');

export class OrderedTable {
  constructor(encode = encodePyKey) {
    this._encode = encode;
    this._slots = [];
    this._index = Object.create(null);
  }

  get size() {
    return this._slots.length;
  }

  contains(key) {
    return this._encode(key) in this._index;
  }

  fetch(key, fallback = MISSING) {
    const slot = this._index[this._encode(key)];
    return slot === undefined ? fallback : this._slots[slot].value;
  }

  /** Insert, or overwrite in place: an existing key keeps its position. */
  put(key, value) {
    const encoded = this._encode(key);
    const slot = this._index[encoded];
