      this._slots.push({ key, value });
    } else {
      this._slots[slot].value = value;
    }
  }

  /** Remove a key if present; returns whether anything was removed. */
  discard(key) {
    const encoded = this._encode(key);
    const slot = this._index[encoded];
    if (slot === undefined) return false;
