 * mapping maintained alongside the forward one.
 *
 * Behaviour reproduced from the reference package:
 *   - construction and item assignment raise on a duplicated value,
 *     overwrite on a duplicated key, and are a no-op when the incoming pair
 *     already exists;
 *   - a pair whose key and value each duplicate a *different* existing pair
 *     raises KeyAndValueDuplicationError;
 *   - repr() is `bidict({...})`, or `bidict()` when empty;
 *   - key order follows first insertion, and overwriting a key's value keeps
 *     that key in place.
 */
import { MISSING, OrderedTable } from './ordered_table.mjs';
import { reprDict } from './pyrepr.mjs';
import {
  DROP_NEW,
  KeyAndValueDuplicationError,
  KeyDuplicationError,
  ON_DUP_DEFAULT,
  RAISE,
  ValueDuplicationError,
} from './bidict_errors.mjs';

export class Bidict {
  static get clsname() {
    return 'bidict';
  }

  /** @param {Array<[any, any]>} [items] initial pairs, in order. */
  constructor(items) {
    this._fwd = new OrderedTable();
    this._inv = new OrderedTable();
    if (items !== undefined) this.update(items);
  }

  get size() {
    return this._fwd.size;
  }

  contains(key) {
    return this._fwd.contains(key);
  }

  /** d[key], or `fallback` when absent. */
  fetch(key, fallback = MISSING) {
    return this._fwd.fetch(key, fallback);
  }

  /** The inverse direction's lookup: value -> key. */
  fetchKey(val, fallback = MISSING) {
    return this._inv.fetch(val, fallback);
  }

  /** d[key] = val */
  setItem(key, val) {
    this.put(key, val, ON_DUP_DEFAULT);
  }

  /** d.update(items) applied pair by pair, left to right. */
  update(items, onDup = ON_DUP_DEFAULT) {
    for (const [key, val] of items) this.put(key, val, onDup);
  }

  /** Assignment with an explicit duplication policy. */
  put(key, val, onDup = ON_DUP_DEFAULT) {
    const dedup = this._dedup(key, val, onDup);
    if (dedup === null) return;
    this._write(key, val, dedup);
  }

  /**
   * Classify the incoming pair against what is already stored and apply the
   * policy.  Returns null when the write must be skipped.
   */
  _dedup(key, val, onDup) {
    const oldval = this._fwd.fetch(key);
    const oldkey = this._inv.fetch(val);
    const isdupkey = oldval !== MISSING;
    const isdupval = oldkey !== MISSING;
    if (isdupkey && isdupval) {
      if (this._sameKey(key, oldkey)) return null; // the exact pair already exists
      if (onDup.kv === RAISE) throw new KeyAndValueDuplicationError(key, val);
      if (onDup.kv === DROP_NEW) return null;
    } else if (isdupkey) {
      if (onDup.key === RAISE) throw new KeyDuplicationError(key);
      if (onDup.key === DROP_NEW) return null;
    } else if (isdupval) {
      if (onDup.val === RAISE) throw new ValueDuplicationError(val);
      if (onDup.val === DROP_NEW) return null;
    }
    return { oldkey, oldval, isdupkey, isdupval };
  }

  _sameKey(key, oldkey) {
    return this._fwd._encode(key) === this._fwd._encode(oldkey);
  }

  _write(newkey, newval, { oldkey, oldval, isdupkey, isdupval }) {
    if (isdupkey) this._inv.discard(oldval);
    if (isdupval) this._fwd.discard(oldkey);
    this._fwd.put(newkey, newval);
    this._inv.put(newval, newkey);
  }

  /** d.pop-less removal: del d[key]. Returns whether the key existed. */
  delItem(key) {
    const oldval = this._fwd.fetch(key);
    if (oldval === MISSING) return false;
    this._fwd.discard(key);
    this._inv.discard(oldval);
    return true;
  }

  clear() {
    this._fwd.clear();
    this._inv.clear();
  }

  items() {
    return this._fwd.items();
  }

  keys() {
    return this._fwd.keys();
  }

  values() {
    return this._fwd.values();
  }

  /** A new bidict with keys and values swapped. */
  inverse() {
    const flipped = new Bidict();
    for (const [val, key] of this._inv.items()) flipped.setItem(val, key);
    return flipped;
  }

  repr() {
    if (this.size === 0) return `${Bidict.clsname}()`;
    return `${Bidict.clsname}(${reprDict(this.items())})`;
  }

  toString() {
    return this.repr();
  }
}

