  _sameKey(key, oldkey) {
    return this._fwd._encode(key) === this._fwd._encode(oldkey);
  }

  _write(newkey, newval, { oldkey, oldval, isdupkey, isdupval }) {
    if (isdupkey) this._inv.discard(oldval);
    if (isdupval) this._fwd.discard(oldkey);
    this._fwd.put(newkey, newval);
    this._inv.put(newval, newkey);
  }

  /** d.pop-less removal: del d[key]. Returns whether the key existed. */
  delItem(key) {
    const oldval = this._fwd.fetch(key);
