    this._fwd.clear();
    this._inv.clear();
  }

  items() {
    return this._fwd.items();
  }

  keys() {
    return this._fwd.keys();
  }

  values() {
    return this._fwd.values();
  }

  /** A new bidict with keys and values swapped. */
  inverse() {
    const flipped = new Bidict();
