export function terminalColumns() {
  const env = process.env.COLUMNS;
  if (env !== undefined) {
    try {
      const columns = Number(pyInt(env));
      if (columns > 0) return columns;
    } catch {
      // Not an int: fall through exactly as Python's ValueError branch does.
    }
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return 80;
}

// Bracketed groups stay whole; everything else splits on whitespace.
