/**
 * A focused re-implementation of the pieces of Python's argparse that the
 * source script uses: long options taking exactly one argument, `type`
 * conversion, `required`, unique-prefix abbreviation, the automatic `-h/--help`,
 * and the exact error/usage/help text (exit status 2 on error, 0 on --help).
 */
import { HelpFormatter } from './help_formatter.mjs';
import { print, writeStderr, writeStdout } from './pyio.mjs';
import { reprStr } from './pyrepr.mjs';

// argparse's own matcher for "this looks like a negative number, not a flag".
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Namespace {
  constructor() {
    // Null prototype so a dest such as 'constructor' cannot collide.
    return Object.create(null);
  }
}

class Action {
  constructor({ optionStrings, dest, type, required, help, metavar, nargs }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.nargs = nargs;
  }

  /** argparse's _get_action_name(). */
  get name() {
    if (this.optionStrings.length > 0) return this.optionStrings.join('/');
    return this.metavar ?? this.dest;
  }
}

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog;
    this._actions = [];
    this._optionStringActions = Object.create(null);
    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        nargs: 0,
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * add_argument(): `flags` is one or more option strings.  `type` is a
   * converter that throws to signal an invalid value; `typeName` names it in
   * the error message ("invalid int value: ...").
   */
  addArgument(flags, { type, typeName = 'str', required = false, help, metavar, nargs = 1, action } = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    const longest = optionStrings.find((flag) => flag.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const created = new Action({
      optionStrings,
      dest,
      type,
      required,
      help,
      metavar: metavar ?? dest.toUpperCase(),
      nargs,
    });
    created.typeName = typeName;
    created.isHelp = action === 'help';
    this._actions.push(created);
    for (const flag of optionStrings) this._optionStringActions[flag] = created;
    return created;
  }

  get _formatter() {
    return new HelpFormatter(this.prog);
  }

  formatUsage() {
    return this._formatter.formatUsage(this._actions);
  }

  formatHelp() {
    const formatter = this._formatter;
    let out = formatter.formatUsage(this._actions);
    out += '\noptions:\n';
    out += formatter.formatActions(this._actions);
    return out;
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** parser.error(): usage plus one message on stderr, then exit status 2. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /**
   * argparse's _parse_optional(): decides whether a token is an option.
   * Returns null when the token is a plain value.
   */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!argString.startsWith('-')) return null;
    const exact = this._optionStringActions[argString];
    if (exact !== undefined) return { action: exact, optionString: argString, explicitArg: null };
    if (argString.length === 1) return null; // a bare '-'
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const known = this._optionStringActions[optionString];
      if (known !== undefined) {
        return { action: known, optionString, explicitArg: argString.slice(eq + 1) };
      }
    }
    const matches = this._getOptionTuples(argString);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];
    if (NEGATIVE_NUMBER.test(argString) && !this._hasNegativeNumberOptionals()) return null;
    if (argString.includes(' ')) return null;
    return { action: null, optionString: argString, explicitArg: null };
  }

  /** argparse's _get_option_tuples(): abbreviation candidates. */
  _getOptionTuples(argString) {
    const result = [];
    if (argString.startsWith('--')) {
      const eq = argString.indexOf('=');
      const prefix = eq === -1 ? argString : argString.slice(0, eq);
      const explicitArg = eq === -1 ? null : argString.slice(eq + 1);
      for (const optionString of Object.keys(this._optionStringActions)) {
        if (optionString.startsWith(prefix)) {
          result.push({ action: this._optionStringActions[optionString], optionString, explicitArg });
        }
      }
    } else {
      const shortPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const optionString of Object.keys(this._optionStringActions)) {
        if (optionString === shortPrefix) {
          result.push({
            action: this._optionStringActions[optionString],
            optionString,
            explicitArg: shortExplicitArg,
          });
        } else if (optionString.startsWith(argString)) {
          result.push({ action: this._optionStringActions[optionString], optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

  _hasNegativeNumberOptionals() {
    return Object.keys(this._optionStringActions).some((flag) => NEGATIVE_NUMBER.test(flag));
  }

  _convert(action, optionString, text) {
    if (action.type === undefined) return text;
    try {
      return action.type(text);
    } catch {
      this.error(`argument ${optionString}: invalid ${action.typeName} value: ${reprStr(text)}`);
      return undefined; // unreachable: error() exits
    }
  }

  /** parse_args(): parse_known_args() plus the unrecognized-arguments check. */
  parseArgs(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    const namespace = new Namespace();
    const extras = [];
    const seen = new Set();
    // Everything after the first '--' is a value, never an option; the
    // separator itself is consumed by neither and ends up unrecognized.
    let afterSeparator = false;
    let i = 0;

    while (i < argv.length) {
      const argString = argv[i];
      if (afterSeparator) {
        extras.push(argString);
        i += 1;
        continue;
      }
      if (argString === '--') {
        afterSeparator = true;
        extras.push(argString);
        i += 1;
        continue;
      }
      const optional = this._parseOptional(argString);
      if (optional === null || optional.action === null) {
        extras.push(argString);
        i += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optional;
      i += 1;
      if (action.isHelp) {
        if (explicitArg !== null && explicitArg !== '') {
          this.error(`argument ${action.name}: ignored explicit argument ${reprStr(explicitArg)}`);
        }
        this.printHelp();
        process.exit(0);
      }
      let raw;
      if (explicitArg !== null) {
        raw = explicitArg;
      } else {
        const next = i < argv.length ? argv[i] : undefined;
        // A '--' separator or another option cannot serve as this value.
        if (next === undefined || next === '--' || this._parseOptional(next) !== null) {
          this.error(`argument ${optionString}: expected one argument`);
        }
        raw = next;
        i += 1;
      }
      namespace[action.dest] = this._convert(action, optionString, raw);
      seen.add(action);
    }

    const missing = this._actions.filter((action) => action.required && !seen.has(action));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.map((action) => action.name).join(', ')}`,
      );
    }
    return [namespace, extras];
  }
}

export { print };

